String fn0(String barcode) {
  if (barcode.isEmpty) return '';

  final List<String> parts = barcode.split(',');

  int total = 0;
  for (final String part in parts) {
    final int letter = part.codeUnitAt(0) - 64;
    final int value = int.parse(part.substring(1));
    total += letter * value;
  }
  final int shift = total % 26;

  final List<String> out = <String>[];
  for (final String part in parts) {
    final int pos = (part.codeUnitAt(0) - 65 + shift) % 26;
    final String letter = String.fromCharCode(pos + 65);
    out.add(letter + part.substring(1));
  }

  return out.join(',');
}

