bool fn0(int n, List<int> steps, List<int> starts, int lo, int hi) {
  if (steps.length != starts.length) {
    return false;
  }
  if (n <= 0) {
    return false;
  }
  final List<int> counts = List<int>.filled(n, 0);
  for (int i = 0; i < steps.length; i++) {
    final int step = steps[i];
    final int start = starts[i];
    if (step <= 0) {
      return false;
    }
    int pos = start % n;
    final int cycle = n ~/ _gcdOf(step, n);
    for (int k = 0; k < cycle; k++) {
      if (lo != -1) {
        if (lo <= hi) {
          if (pos >= lo && pos <= hi) {
            return false;
          }
        } else {
          if (pos >= lo || pos <= hi) {
            return false;
          }
        }
      }
      counts[pos] = counts[pos] + 1;
      if (counts[pos] > 1) {
        return false;
      }
      pos = (pos + step) % n;
    }
  }
  return true;
}

int _gcdOf(int a, int b) {
  while (b != 0) {
    final int t = a % b;
    a = b;
    b = t;
  }
  return a;
}

